import sys

with open('/workspaces/nutricare-frontend/app.html', 'r', encoding='utf-8') as f:
    content = f.read()

start_marker = 'function renderPredictionTab() {'
end_marker = '\nfunction renderActiviteTab() {'

start_idx = content.find(start_marker)
if start_idx == -1:
    print('ERREUR: fonction renderPredictionTab introuvable')
    sys.exit(1)
end_idx = content.find(end_marker, start_idx)
if end_idx == -1:
    print('ERREUR: renderActiviteTab introuvable apres la fonction')
    sys.exit(1)

func_code_v2 = 'function renderPredictionTab() {\n  var contentEl = document.getElementById(\'predictionContent\');\n  if (!contentEl) return;\n  contentEl.innerHTML = \'<div style="text-align:center;padding:30px 0;color:#888;font-size:0.85rem">Analyse en cours...</div>\';\n  var token = localStorage.getItem(\'nutricare_token\');\n  fetch(BACKEND_URL + \'/api/health/predict\', {\n    method: \'GET\',\n    headers: {\'Content-Type\':\'application/json\', \'Authorization\': \'Bearer \' + token}\n  }).then(function(r){return r.json();}).then(function(d){\n    if (d.error) {\n      contentEl.innerHTML = \'<div style="text-align:center;padding:20px 0;color:#888;font-size:0.85rem">Impossible de charger la prediction pour le moment.</div>\';\n      return;\n    }\n    if (!d.suffisant) {\n      var pct = Math.round((d.jours_disponibles / d.jours_requis) * 100);\n      contentEl.innerHTML =\n        \'<div style="text-align:center;padding:10px 0 20px">\' +\n          \'<i class="ti ti-telescope" style="font-size:32px;color:#ddd;margin-bottom:10px;display:block"></i>\' +\n          \'<div style="font-size:0.85rem;color:#666;margin-bottom:14px">\' + d.message + \'</div>\' +\n          \'<div style="background:#F0EEE9;border-radius:8px;height:6px;overflow:hidden;margin-bottom:6px;max-width:220px;margin-left:auto;margin-right:auto">\' +\n            \'<div style="background:linear-gradient(90deg,#FF9A3C,#FF6B6B);height:100%;width:\' + Math.min(100,pct) + \'%"></div>\' +\n          \'</div>\' +\n          \'<div style="font-size:0.72rem;color:#aaa">\' + d.jours_disponibles + \' / \' + d.jours_requis + \' jours de suivi</div>\' +\n        \'</div>\';\n      return;\n    }\n    var couleurs = { faible: \'#3BA65C\', moderee: \'#E8983C\', elevee: \'#E85C5C\' };\n    var couleursBg = { faible: \'#E8F5EC\', moderee: \'#FDF1E4\', elevee: \'#FCEAEA\' };\n    var couleur = couleurs[d.niveau_vigilance] || \'#E8983C\';\n    var couleurBg = couleursBg[d.niveau_vigilance] || \'#FDF1E4\';\n\n    var html = \'\';\n    html += \'<div style="display:inline-flex;align-items:center;gap:6px;background:\' + couleurBg + \';border-radius:20px;padding:5px 13px;margin-bottom:12px">\' +\n        \'<span style="width:7px;height:7px;border-radius:50%;background:\' + couleur + \'"></span>\' +\n        \'<span style="font-size:0.72rem;font-weight:700;color:\' + couleur + \';text-transform:uppercase;letter-spacing:0.03em">Vigilance \' + d.niveau_vigilance + \'</span>\' +\n      \'</div>\';\n    html += \'<div style="font-size:1.1rem;font-weight:700;color:#2D2D2D;margin-bottom:8px">\' + d.titre + \'</div>\';\n    if (d.resume) {\n      html += \'<div style="font-size:0.87rem;color:#555;line-height:1.6;margin-bottom:16px">\' + d.resume + \'</div>\';\n    }\n\n    if (d.tendances_observees && d.tendances_observees.length) {\n      html += \'<div style="font-size:0.72rem;font-weight:700;color:#999;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:8px">Tendances observees</div>\';\n      html += \'<div style="margin-bottom:18px">\';\n      d.tendances_observees.forEach(function(t) {\n        html += \'<div style="display:flex;align-items:flex-start;gap:8px;margin-bottom:6px">\' +\n          \'<i class="ti ti-trending-down" style="font-size:15px;color:#999;margin-top:2px;flex-shrink:0"></i>\' +\n          \'<span style="font-size:0.82rem;color:#555;line-height:1.4">\' + t + \'</span></div>\';\n      });\n      html += \'</div>\';\n    }\n\n    if (d.risques && d.risques.length) {\n      html += \'<div style="font-size:0.72rem;font-weight:700;color:#999;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:8px">Risques identifies</div>\';\n      html += \'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px">\';\n      d.risques.forEach(function(r) {\n        var rc = couleurs[r.niveau === \'eleve\' ? \'elevee\' : r.niveau === \'modere\' ? \'moderee\' : \'faible\'];\n        var rbg = couleursBg[r.niveau === \'eleve\' ? \'elevee\' : r.niveau === \'modere\' ? \'moderee\' : \'faible\'];\n        html += \'<div style="background:\' + rbg + \';border-radius:10px;padding:6px 12px;font-size:0.76rem;font-weight:600;color:\' + rc + \'">\' + (r.label || r.type) + \'</div>\';\n      });\n      html += \'</div>\';\n    }\n\n    if (d.conseils && d.conseils.length) {\n      html += \'<div style="font-size:0.72rem;font-weight:700;color:#999;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:10px">Conseils de Mirella</div>\';\n      d.conseils.forEach(function(c) {\n        html += \'<div style="background:#FFF6EF;border-radius:12px;padding:12px 14px;margin-bottom:10px;display:flex;gap:10px;align-items:flex-start">\' +\n          \'<i class="ti ti-bulb" style="font-size:17px;color:#FF9A3C;flex-shrink:0;margin-top:1px"></i>\' +\n          \'<div><div style="font-size:0.85rem;font-weight:700;color:#2D2D2D;margin-bottom:2px">\' + c.titre + \'</div>\' +\n          \'<div style="font-size:0.8rem;color:#666;line-height:1.5">\' + c.description + \'</div></div>\' +\n        \'</div>\';\n      });\n    }\n\n    contentEl.innerHTML = html;\n  }).catch(function(e){\n    console.error(e);\n    contentEl.innerHTML = \'<div style="text-align:center;padding:20px 0;color:#888;font-size:0.85rem">Erreur de connexion. Reessayez plus tard.</div>\';\n  });\n}\n'
new_content = content[:start_idx] + func_code_v2.strip() + content[end_idx:]

with open('/workspaces/nutricare-frontend/app.html', 'w', encoding='utf-8') as f:
    f.write(new_content)

print('OK: fonction renderPredictionTab remplacee par la version enrichie')
